// Update all 25 locale files
for (const lang of languages) {
  const filePath = path.join(localesDir, `${lang}.json`);
  let content = {};
  if (fs.existsSync(filePath)) {
    content = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  }

  for (const [keyPath, langMap] of Object.entries(translations)) {
    const val = langMap[lang] || langMap['en'] || '';
    setNested(content, keyPath, val);
  }

  fs.writeFileSync(filePath, JSON.stringify(content, null, 2) + '\n', 'utf8');
  console.log(`Updated ${lang}.json`);
}

console.log('All translations successfully synced across all 25 locales!');
